package com.autojobapply.discovery;
import com.autojobapply.config.Config; import com.autojobapply.matching.JobMatcher; import com.autojobapply.model.*; import com.autojobapply.tracking.ApplicationTracker; import java.util.*;
public final class GreenhousePipelineService { private final GreenhouseCompanyDiscoveryService companies;private final GreenhouseJobDiscoveryService jobs;private final ApplicationTracker tracker;private final JobMatcher matcher;private final Config config; private GreenhousePipelineReport report=new GreenhousePipelineReport(); public GreenhousePipelineService(GreenhouseCompanyDiscoveryService c,GreenhouseJobDiscoveryService j,ApplicationTracker t,JobMatcher m,Config x){companies=c;jobs=j;tracker=t;matcher=m;config=x;}
 public GreenhousePipelineReport report(){return report;}
 public List<ScoredJob> run()throws Exception{report=new GreenhousePipelineReport();report.executionMode(config.executionMode().name());report.directoryEntered();List<GreenhouseCompanyDiscoveryService.Board> discovered;try{discovered=companies.discover();report.directoryCompleted(discovered.size());}catch(Exception e){report.directoryFailed(e);throw new IllegalStateException("Greenhouse directory download failed; discovery was not skipped",e);}List<GreenhouseCompanyDiscoveryService.Board> selected=discovered.stream().limit(50).toList();report.employersSelected(selected.size(),discovered.size()-selected.size());List<ScoredJob> out=new ArrayList<>();for(GreenhouseCompanyDiscoveryService.Board b:selected){GreenhouseCompanyDiscoveryService.Validation validation=companies.validateDetailed(b);report.validated(validation.valid(),validation.reason());tracker.saveEmployer(b.token(),b.company(),b.boardUrl(),b.apiUrl(),b.source(),validation.valid());if(!validation.valid())continue;try{List<Job> retrieved=jobs.retrieve(b);report.retrieved(retrieved.size());for(Job job:retrieved){tracker.saveGreenhouseJob(b.token(),job);if(tracker.isKnown(job)){report.known();continue;}report.matchingEntered();ScoredJob s=matcher.score(job);tracker.record(s,s.eligible()?ApplicationStatus.MATCHED:ApplicationStatus.SKIPPED,null);if(!s.eligible()){report.ineligible();continue;}report.matched();tracker.enqueue(b.token(),s);report.queued();out.add(s);}}catch(Exception e){report.retrievalFailed(b.token(),e);}}if(report.noBoardCouldBeValidatedBecauseOfErrors())throw new IllegalStateException("Greenhouse board validation failed for every selected board; see diagnostics for HTTP errors");if(report.allRetrievalsFailed())throw new IllegalStateException("Greenhouse job retrieval failed for every validated board; see diagnostics for HTTP errors");return out;}}
